function snapshotRegistry(operations) {
  const sets = [], results = [];
  for (const op of operations) {
    if (op[0] === 'set') sets.push(op);
    else {
      let best = null;
      for (const s of sets) if (s[1] === op[1] && s[3] <= op[2] && (!best || s[3] > best[3])) best = s;
      results.push(best ? best[2] : '');
    }
  }
  return results;
}

class Registry {
  #history = new Map();
  set(key, value, time) {
    if (!this.#history.has(key)) this.#history.set(key, { times: [], values: [] });
    const h = this.#history.get(key);
    h.times.push(time);
    h.values.push(value);
  }
  get(key, time) {
    const h = this.#history.get(key);
    if (!h) return '';
    let lo = 0, hi = h.times.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (h.times[mid] <= time) lo = mid + 1; else hi = mid;
    }
    return lo ? h.values[lo - 1] : '';
  }
}

function snapshotRegistry(operations) {
  const registry = new Registry(), results = [];
  for (const op of operations) {
    if (op[0] === 'set') registry.set(op[1], op[2], op[3]);
    else results.push(registry.get(op[1], op[2]));
  }
  return results;
}
